#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    vector<char> color(4, 0);
    vector<int> missing(4, 0);
    set<char> unused = {'R', 'B', 'Y', 'G'};

    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] == '!')
            ++missing[i % 4];
        else {
            color[i % 4] = s[i];
            unused.erase(s[i]);
        }
    }

    for (int i = 0; i < 4; ++i) {
        if (color[i] == 0) {
            color[i] = *unused.begin();
            unused.erase(unused.begin());
        }
    }

    map<char, int> answer;
    for (int i = 0; i < 4; ++i)
        answer[color[i]] += missing[i];

    cout << answer['R'] << ' ' << answer['B'] << ' '
         << answer['Y'] << ' ' << answer['G'] << '\n';

    return 0;
}

